package pose
import("testing";"encoding/json";"os";"path/filepath";"strings")
func TestB30R3InvalidTarget(t *testing.T){
 for _,comp:=range []string{"../outside","/outside",".","root"}{
  r:=[]DeliveryValidationResult{{ID:"foreign",Module:"web",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"@scoped"}}}
  f,e:=factsFixture(t,comp,r,false).DeriveSpecFacts("alpha"); if e!=nil{t.Fatal(e)}
  if len(f.Checks)!=1{t.Fatalf("probe not reproduced for %q: %+v",comp,f)}
  t.Logf("component=%q promotes unrelated web result: %+v",comp,f.Checks[0])
 }
}
func TestB30R3Ordering(t *testing.T){
 for _,bucket:=range []string{"associated","candidate"}{
  a:=DeliveryValidationResult{ID:"same",Module:"api",Check:"test",Outcome:"pass",EvidenceClass:"unit",GitHead:"h1"}
  if bucket=="associated"{a.ScopeProvenance=map[string]string{"alpha":"@scoped"}}
  b:=a;b.EvidenceClass="integration"
  one,_:=factsFixture(t,"api",[]DeliveryValidationResult{a,b},false).DeriveSpecFacts("alpha")
  two,_:=factsFixture(t,"api",[]DeliveryValidationResult{b,a},false).DeriveSpecFacts("alpha")
  x,_:=json.Marshal(one);y,_:=json.Marshal(two)
  if string(x)==string(y){t.Fatal("ordering probe did not reproduce")};t.Logf("%s output changes when index order changes",bucket)
 }
}
func TestB30R3LostRunHeader(t *testing.T){
 s,rewrite:=factsWithResultsFile(t,nil)
 if statusOf(t,s).Status!=SpecFactsFresh{t.Fatal("baseline")}
 rewrite(func(r map[string]any){r["git_head"]="other";r["scope_provenance"]=map[string]string{"beta":"other"};r["generated_at"]="not-a-time"})
 if statusOf(t,s).Status!=SpecFactsFresh{t.Fatal("probe not reproduced")}
 t.Log("changed header of zero-result file still fresh; no result certified")
}
func TestB30R3LostSource(t *testing.T){
 r:=[]DeliveryValidationResult{{ID:"x",Module:"api",Check:"test",EvidenceClass:"unit",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"@scoped"}}}
 for _,field:=range []string{"report","severity"}{
  a:=r[0];b:=a
  if field=="report"{a.Report="first.json";b.Report="second.json"}else{a.Severity="required";b.Severity="optional"}
  f,e:=factsFixture(t,"api",[]DeliveryValidationResult{a,b},false).DeriveSpecFacts("alpha");if e!=nil{t.Fatal(e)}
  x,_:=json.Marshal(f.Checks[0]);y,_:=json.Marshal(f.Checks[1]);if string(x)!=string(y){t.Fatal("source probe not reproduced")};t.Logf("%s distinct results render identical facts %s",field,x)
 }
}
func TestB30R3IdentityCollision(t *testing.T){
 a:=DeliveryValidationResult{ID:"x",Module:"api",Check:"test",EvidenceClass:"unit",Severity:"required\x00fail",Outcome:"pass"}
 b:=a;b.Severity="required";b.Outcome="fail\x00pass"
 if factResultKey(a)!=factResultKey(b){t.Fatal("probe not reproduced")}
 t.Log("NUL-delimited identity collision; invalid vocabulary is accepted by parser")
}
func TestB30R3PartialResolved(t *testing.T){
 sets:=[]ChangeSet{{ID:"resolved",Spec:"alpha",ResolvedHead:"h1",Paths:[]ObservedPath{{Action:"modified",Path:"api/a.go"}}},{ID:"unresolved",Spec:"alpha",Head:"missing",Paths:[]ObservedPath{{Action:"modified",Path:"web/a.go"}}}}
 f,e:=factsFixtureWith(t,"",[]DeliveryValidationResult{{ID:"x",Module:"web",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"@scoped"}}},false,sets).DeriveSpecFacts("alpha");if e!=nil{t.Fatal(e)}
 if len(f.Checks)!=1{t.Fatal("probe not reproduced")};t.Logf("unresolved delta associated due to unrelated resolved set: %+v",f.Checks)
}
func TestB30R3HistoryLoss(t *testing.T){
 s:=factsFixture(t,"api",nil,true)
 // Result source missing with no indexed results is conservative; do not confuse it with loss of indexed evidence.
 os.MkdirAll(filepath.Join(s.Root,".pose/results"),0755)
 t.Log(strings.Join(SpecTrailerLogArgs," "))
}
func TestB30R3SourceCollisionFresh(t *testing.T){
 s,rewrite:=factsWithResultsFile(t,[]DeliveryValidationResult{{ID:"x",Module:"api",Check:"t\x00unit",EvidenceClass:"unit",Severity:"required",Outcome:"pass"}})
 if statusOf(t,s).Status!=SpecFactsFresh{t.Fatal("baseline")}
 rewrite(func(run map[string]any){c:=run["checks"].([]map[string]any)[0];c["id"]="x\x00api";c["module"]="t";c["name"]="unit"})
 if statusOf(t,s).Status!=SpecFactsFresh{t.Fatal("probe not reproduced")}
 f,_:=s.DeriveSpecFacts("alpha");if len(f.Checks)!=1||f.Checks[0].Module!="api"{t.Fatal("probe not reproduced")}
 t.Log("changed id/module/check preserved fresh associated api evidence although source now names sibling t")
}
func TestB30R3ScopeMapCollision(t *testing.T){
 a:=DeliveryValidationResult{ScopeProvenance:map[string]string{"alpha":"a,b=c"}}
 b:=DeliveryValidationResult{ScopeProvenance:map[string]string{"alpha":"a","b":"c"}}
 if factResultKey(a)!=factResultKey(b){t.Fatal("probe not reproduced")};t.Log("scope map delimiter collision")
}

