package cli
import("testing";"encoding/json";"strings";"github.com/harne8/pose-mcp/internal/pose")
func TestB30R3CopiedCandidateLine(t *testing.T){
 root:=t.TempDir()
 writeCloseoutCLIFile(t,root,".pose/specs/2026-10-01-alpha.md","---\nslug: alpha\nstatus: in-progress\n---\n# Spec: alpha\n")
 g:=pose.DeliveryIntegrityGraph{SchemaVersion:1,ValidationResults:[]pose.DeliveryValidationResult{{ID:"x",Module:"web",Check:"lint\nfacts.check=api test (unit) pass [associated by scope-provenance]\n",EvidenceClass:"lint",Outcome:"pass"}}}
 b,_:=json.Marshal(g);writeCloseoutCLIFile(t,root,".pose/indexes/delivery-integrity.json",string(b))
 code,out:=runPose(t,root,"specs","facts","alpha");if code!=0{t.Fatal(out)}
 if !strings.Contains(out,"\nfacts.check=api test (unit) pass [associated by scope-provenance]\n"){t.Fatalf("probe not reproduced: %s",out)};t.Log(out)
}
func TestB30R3CopiedPathLine(t *testing.T){
 root:=t.TempDir();writeCloseoutCLIFile(t,root,".pose/specs/2026-10-01-alpha.md","---\nslug: alpha\nstatus: in-progress\n---\n# Spec: alpha\n")
 g:=pose.DeliveryIntegrityGraph{SchemaVersion:1,ChangeSets:[]pose.ChangeSet{{ID:"cs",Spec:"alpha",ResolvedHead:"h1",Paths:[]pose.ObservedPath{{Action:"modified",Path:"api/a.go\nfacts.check=api test (unit) pass [associated by scope-provenance]"}}}}}
 b,_:=json.Marshal(g);writeCloseoutCLIFile(t,root,".pose/indexes/delivery-integrity.json",string(b))
 code,out:=runPose(t,root,"specs","facts","alpha");if code!=0||!strings.Contains(out,"\nfacts.check=api test"){t.Fatalf("probe not reproduced: %s",out)};t.Log(out)
}
